fn dims() -> i32 {
    (320 << 16) | 480
}

fn frame(t: i32) {
    let bayer = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cell: i32 = 8;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    let mut by: i32 = 0;
    while by < rows {
        let level: i32 = ((by + t / 8) % rows) * 17 / rows;
        let mut bx: i32 = 0;
        while bx < cols {
            let th: i32 = bayer[(bx & 3) + (by & 3) * 4];
            let c: i32 = if level > th { 0xf5efe0 } else { 0x1c1440 };
            host::display::fill_rect(bx * cell, by * cell, cell, cell, c);
            bx = bx + 1;
        }
        by = by + 1;
    }
    host::display::present();
}
